Nos explicas la primera  def ordenar(notas: list[dict]) -> list[dict]:
    """Ver TAREAS.md, tarea t16."""
    return sorted(
        notas,
        key=lambda n: (
            -n["prioridad"],
            n["vence"] is None,
            n["vence"] or "",
        ),
    )

